def count_black_squares(N):
    # Assume (1, 1) is black. Standard chessboard coloring.
    N_sq = N * N
    if N % 2 == 0:
        return N_sq // 2
    else:
        # If N is odd, one color has (N^2+1)/2 squares, the other (N^2-1)/2.
        # Since (1, 1) is black, and 1+1=2 (even), B wins the tie.
        return (N_sq + 1) // 2

# Test cases for N = 3k
N_test = [3, 9, 15, 6, 12]
results = {}
for N in N_test:
    B = count_black_squares(N)
    results[N] = B % 3
    print(f"N={N}, |B|={B}, |B| mod 3 = {results[N]}")
